'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cleanText=s=>String(s).replace(/<[^>]+>/g,' ').replace(/\[\[[^\]]+\]\]/g,' ').replace(/\s+/g,' ').trim();
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let storageWorks=true,saved={};
try {saved=JSON.parse(localStorage.getItem('kz-atlas-v1')||'{}')||{};} catch {storageWorks=false;}
const blankNote=()=>({name:'my_kz_binds',text:'',updated:''});
const safeNote=x=>x&&typeof x==='object'?{name:String(x.name||'my_kz_binds').slice(0,60),text:String(x.text||'').slice(0,100000),updated:String(x.updated||'')}:blankNote();
const state={game:saved.game==='cs2'?'cs2':'csgo',lang:saved.lang==='en'?'en':'fr',done:Array.isArray(saved.done)?saved.done.filter(id=>LESSONS.some(l=>l.id===id)):[],logs:Array.isArray(saved.logs)?saved.logs.filter(x=>x&&typeof x==='object'&&typeof x.id==='string').slice(0,100):[],routine:Array.isArray(saved.routine)?saved.routine.filter(x=>Number.isInteger(x)&&x>=0&&x<4):[],bindNotes:{csgo:safeNote(saved.bindNotes?.csgo),cs2:safeNote(saved.bindNotes?.cs2)}};
let page='',svgId=0,seqIndex=0,seqTimer=null,toastTimer=null;
const bindPrefs={layout:'qwerty',crouch:'c',wheel:'mwheeldown',extra:'mouse4',move:false,plugin:true};
const t=(fr,en)=>state.lang==='en'?en:fr;
const lessons=()=>state.lang==='en'?LESSONS_EN:LESSONS;
const sources=()=>state.lang==='en'?SOURCES_EN:SOURCES;
const videos=()=>state.lang==='en'?VIDEOS_EN:VIDEOS;
const glossary=()=>state.lang==='en'?GLOSSARY_EN:GLOSSARY;
const gameName=()=>state.game==='csgo'?'CS:GO':'CS2';
const note=()=>state.bindNotes[state.game];
function persist(){try{localStorage.setItem('kz-atlas-v1',JSON.stringify(state));storageWorks=true;return true;}catch{storageWorks=false;return false;}}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
const CHROME={skip:['Aller au contenu','Skip to content'],fieldmanual:['MANUEL DE TERRAIN','FIELD MANUAL'],manual:['Manuel','Manual'],mybinds:['Mes binds','My binds'],practice:['Pratique','Practice'],index:['Sommaire','Index'],progress:['LEÇONS LUES','LESSONS READ'],sources:['Sources & méthode ↗','Sources & method ↗'],references:['Références ↗','References ↗'],footer:['Guide indépendant · édition locale 02','Independent guide · local edition 02'],searchmanual:['Rechercher dans le manuel','Search the manual'],searchfoot:['Échap pour fermer · Manuel disponible hors ligne','Esc to close · Manual available offline']};
function chrome(){document.documentElement.lang=state.lang;$$('[data-i18n]').forEach(el=>el.textContent=t(...CHROME[el.dataset.i18n]));$$('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===state.lang)));$$('[data-game]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.game===state.game)));$('.search-trigger').setAttribute('aria-label',t('Rechercher','Search'));$('#search-input').setAttribute('aria-label',t('Rechercher dans le manuel','Search the manual'));$('#sidebar').setAttribute('aria-label',t('Sommaire','Index'));$('.primary-nav').setAttribute('aria-label',t('Navigation principale','Main navigation'));$('.footer-status').innerHTML='<i></i> '+t('DISPONIBLE HORS LIGNE','OFFLINE READY');$$('[data-nav]').forEach(a=>{const selected=a.dataset.nav==='manual'?(page==='home'||lessons().some(l=>l.id===page)):a.dataset.nav==='notebook'?['binds','notebook'].includes(page):page==='training';a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function sourceLinks(ids){const data=sources();return `<div class="source-links" aria-label="${t('Sources de cette leçon','Lesson sources')}">${ids.map(id=>data[id]?`<a href="${data[id].url}" target="_blank" rel="noopener noreferrer">${escapeHTML(data[id].title)} ↗</a>`:'').join('')}</div>`;}
const FIGURE_TRANSLATIONS=[
['Blocs KZ en perspective et trajectoire schématique entre deux plateformes','KZ blocks in perspective with a schematic trajectory between platforms'],['Longjump de profil : approche, trajectoire aérienne, réception accroupie sur un bloc de même hauteur.','Side view of a longjump: approach, flight and crouched landing on a block at the same height.'],['Ladderjump : monter et sortir au sommet sans appui au sol, puis rejoindre une plateforme. La ligne pointillée indique la même hauteur.','Ladderjump: climb and leave the top without touching the ground, then reach the platform. The dashed line marks equal height.'],['Vue de dessus : alterner un virage à gauche avec A, puis un virage à droite avec D. Le dessin exagère les courbes.','Top view: alternate a left turn with A and a right turn with D. The curves are exaggerated.'],['Approche vue de dessus : partir du même repère et suivre un arc régulier vers le bord du bloc.','Top view of the approach: start at the same point and follow a smooth arc towards the edge.'],['Bunnyhop : trajectoires successives avec réceptions marquées comme points de préparation du saut suivant.','Bunnyhop: consecutive jumps with landing points used to prepare the next jump.'],['Volume debout et volume accroupi schématiques : l’accroupissement aide à faire passer les pieds sur un obstacle.','Schematic standing and crouched collision volumes: crouching helps your feet clear an obstacle.'],['Route composée de trois blocs après un checkpoint : isoler chaque passage avant de relier la section.','Three-block route after a checkpoint: practise each jump before linking the section.'],
['Schéma pédagogique original · non à l’échelle · aucun calcul physique.','Original teaching diagram · not to scale · no physics simulation.'],['LAJ classique schématique · le trait représente la trajectoire, pas une touche saut obligatoire · critères GOKZ.','Schematic LAJ · the line shows a trajectory, not a required jump-button press · GOKZ criteria.'],['Trajectoire exagérée pour expliquer la coordination · QWERTY · aucune amplitude optimale imposée.','Exaggerated trajectory to explain coordination · QWERTY · no prescribed optimal turn size.'],
['01 / DÉPART','01 / TAKEOFF'],['02 / ARRIVÉE','02 / LANDING'],['TRAJECTOIRE','TRAJECTORY'],['01 · APPROCHE','01 · APPROACH'],['02 · VOL','02 · FLIGHT'],['03 · RÉCEPTION','03 · LANDING'],['VIDE / BLOCK','GAP / BLOCK'],['MONTER → SORTIR → GUIDER','CLIMB → EXIT → STEER'],['MÊME HAUTEUR','SAME HEIGHT'],['LAJ : SORTIE SANS APPUI AU SOL','LAJ: EXIT WITHOUT GROUND CONTACT'],['LAH = ÉCHELLE + SOL,','LAH = LADDER + GROUND,'],['PUIS SAUT','THEN JUMP'],['VUE DE DESSUS / STRAFE AVANT','TOP VIEW / FORWARD STRAFE'],['A / SOURIS À GAUCHE','A / MOUSE LEFT'],['D / SOURIS À DROITE','D / MOUSE RIGHT'],['A / GAUCHE','A / LEFT'],['AVANCE RELÂCHÉE','FORWARD RELEASED'],['APPROCHE / VUE DE DESSUS','APPROACH / TOP VIEW'],['DÉPART FIXE','FIXED START'],['DE SORTIE','OF EXIT'],['UN VIRAGE RÉGULIER','ONE SMOOTH TURN'],['BORD','EDGE'],['RÉCEPTION → SAUT SUIVANT','LANDING → NEXT JUMP'],['PRÉPARER LE CONTACT','PREPARE THE CONTACT'],['ENCHAÎNER','LINK JUMPS'],['VOLUME DE COLLISION / VUE DE CÔTÉ','COLLISION VOLUME / SIDE VIEW'],['DEBOUT','STANDING'],['ACCROUPI','CROUCHED'],['LE GESTE DÉPEND','THE MOVEMENT DEPENDS'],['DE L’OBSTACLE','ON THE OBSTACLE'],['UN PASSAGE À LA FOIS','ONE JUMP AT A TIME'],['DÉPART','TAKEOFF'],['ARRIVÉE','LANDING']
];
function figureText(str){if(state.lang!=='en')return str;for(const [fr,en] of FIGURE_TRANSLATIONS)str=str.split(fr).join(en);return str;}
const PHASES=[
{title:['Préparer l’approche','Prepare the approach'],text:['Pars du même repère. En mode modifié, travaille le prestrafe propre au serveur ; en VNL, cherche une course régulière.','Start from the same point. In modified modes, practise the server’s prestrafe; in VNL, aim for a consistent run-up.'],keys:['W'],x:80,y:206},
{title:['Décoller, relâcher l’avance','Take off, release forward'],text:['Déclenche le saut près du bord. Pour cet exercice de strafe avant, relâche W au décollage.','Jump close to the edge. For this forward-strafing exercise, release W as you take off.'],keys:['JUMP','W ↑'],x:149,y:198},
{title:['Premier strafe à gauche','First strafe to the left'],text:['Maintiens A et tourne la souris doucement à gauche. Ne garde pas W pour cette séquence de base.','Hold A and turn the mouse smoothly to the left. Do not hold W in this basic sequence.'],keys:['A','MOUSE ←'],x:234,y:104},
{title:['Changer de côté','Switch sides'],text:['Relâche A, prends D et inverse le virage vers la droite. La démonstration montre seulement deux strafes, sans imposer de nombre optimal.','Release A, press D and turn to the right. This demonstration shows two strafes without prescribing an optimal number.'],keys:['D','MOUSE →'],x:343,y:106},
{title:['Atteindre la réception','Reach the landing'],text:['Vise le bloc. Utilise le crouch quand le franchissement du bord le demande. Ici C désigne la touche accroupissement du preset.','Aim for the block. Crouch when you need to clear the edge. Here C is the crouch key in the preset.'],keys:['C'],x:452,y:206,crouch:true}
];
function sequence(){return `<div class="sequencer"><div class="seq-top"><span>LJ / ${t('DÉCOMPOSITION','BREAKDOWN')}</span><span id="seq-count"></span></div><div class="seq-stage"><div id="seq-svg"></div><div class="seq-timeline" aria-label="${t('Phases du longjump','Longjump phases')}">${PHASES.map((p,i)=>`<button data-phase="${i}" aria-label="${i+1}. ${t(...p.title)}"></button>`).join('')}</div><div class="seq-description"><div class="keys" id="seq-keys"></div><div><h3 id="seq-title"></h3><p id="seq-text"></p></div></div></div><div class="seq-controls"><button data-action="seq-prev" aria-label="${t('Phase précédente','Previous phase')}">←</button><button data-action="seq-play" id="seq-play">${t('Lire la séquence','Play sequence')}</button><span class="seq-caption">${t('Ordre illustratif, pas un timing réel','Illustrative order, not real timing')}</span><button data-action="seq-next" aria-label="${t('Phase suivante','Next phase')}">→</button></div></div>`;}
function drawSequence(){if(!$('#seq-svg'))return;const p=PHASES[seqIndex];$('#seq-svg').innerHTML=svgWrap(`${block(30,206,142,50)}${block(424,206,146,50)}<path d="M145 205Q293-60 452 205" fill="none" stroke="#698950" stroke-width="1.5" stroke-dasharray="4 5"/>${PHASES.map((s,i)=>`<circle cx="${s.x}" cy="${s.y}" r="3" fill="${i<=seqIndex?'#c6f779':'#4d613e'}"/>`).join('')}${player(p.x,p.y,p.crouch)}<text x="45" y="35" fill="#c6f779">0${seqIndex+1} / ${t(...p.title).toUpperCase()}</text><text x="68" y="239" font-size="9">DÉPART</text><text x="461" y="239" font-size="9">ARRIVÉE</text>`,t(...p.title));$('#seq-count').textContent=`0${seqIndex+1} / 05`;$('#seq-keys').innerHTML=p.keys.map(x=>`<kbd class="key">${state.lang==='fr'?x.replace('JUMP','SAUT').replace('MOUSE','SOURIS'):x}</kbd>`).join('');$('#seq-title').textContent=t(...p.title);$('#seq-text').textContent=t(...p.text);$$('[data-phase]').forEach((b,i)=>{b.classList.toggle('active',i===seqIndex);b.setAttribute('aria-pressed',String(i===seqIndex));});}
function stopSequence(){clearInterval(seqTimer);seqTimer=null;if($('#seq-play'))$('#seq-play').textContent=t('Lire la séquence','Play sequence');}
function navigation(){const ls=lessons();$('#navigation').innerHTML=`<a class="nav-link ${page==='home'?'active':''}" href="#home"><span class="nav-num">00</span>${t('Vue d’ensemble','Overview')}</a>`+[...new Set(ls.map(l=>l.group))].map(group=>`<div class="nav-group"><div class="nav-label">${group}</div>${ls.filter(l=>l.group===group).map(l=>`<a class="nav-link ${page===l.id?'active':''}" href="#${l.id}" ${page===l.id?'aria-current="page"':''}><span class="nav-num">${l.number}</span>${l.short}${state.done.includes(l.id)?'<span class="nav-tick">✓</span>':''}</a>`).join('')}</div>`).join('')+`<div class="nav-group"><div class="nav-label">${t('ATELIER','WORKSHOP')}</div>${[['notebook','⌘',t('Mes binds','My binds')],['binds','↗',t('Générateur CFG','CFG generator')],['training','↗',t('Entraînement','Practice')],['glossary','Aa',t('Lexique','Glossary')]].map(([id,n,title])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}"><span class="nav-num">${n}</span>${title}</a>`).join('')}</div>`;$('#progress-count').textContent=`${state.done.length} / ${ls.length}`;$('#progress-fill').style.width=(state.done.length/ls.length*100)+'%';chrome();}
function header(title,intro,eyebrow=t('KZ ATLAS / MANUEL','KZ ATLAS / MANUAL')){return `<div class="article-header"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${intro}</p></div>`;}
function home(){const ls=lessons();const next=ls.find(l=>!state.done.includes(l.id))||ls[0];return `<section class="cover"><div class="cover-line"><span>${t('ÉTUDES DU MOUVEMENT','MOVEMENT STUDIES')}</span><span>VOL. 02 / CS:GO — CS2</span></div><h1 class="cover-title">KREEDZ<span>CLIMBING.</span></h1><div class="cover-spread"><div class="cover-notes"><span class="edition-label">KZ / ATLAS<br>${t('ÉDITION DE TERRAIN','FIELD EDITION')}</span><p>${t('Un manuel pour comprendre ce qui se passe entre deux blocs.','A manual to understand what happens between two blocks.')}</p><div class="cover-details"><span>11 ${t('LEÇONS','LESSONS')}</span><span>02 ${t('JEUX','GAMES')}</span><span>FR / EN</span></div><a class="btn" href="#${next.id}">${state.done.length?t('Reprendre le parcours','Continue learning'):t('Ouvrir le manuel','Open the manual')} <span>↗</span></a><small>${t('Ta progression','Your progress')} <span>${state.done.length} / 11</span></small></div><a class="cover-plate" href="#longjump"><div class="plate-top"><span>FIG. 05 / LONGJUMP</span><span>${t('OUVRIR LA PLANCHE','OPEN THE STUDY')} ↗</span></div>${isoHero()}<div class="plate-bottom"><span>01 ${t('APPROCHE','APPROACH')}</span><span>02 ${t('VOL','FLIGHT')}</span><span>03 ${t('RÉCEPTION','LANDING')}</span></div><span class="plate-note">${t('Schéma hors échelle','Diagram not to scale')}</span></a></div></section><section class="index-section"><div class="index-heading"><h2>${t('Sommaire','Contents')}<sup>01—11</sup></h2><span>${t('LIRE. ESSAYER. RECOMMENCER.','READ. TRY. REPEAT.')}</span></div><div class="chapter-columns">${[...new Set(ls.map(l=>l.group))].map((group,i)=>`<div class="chapter-group"><div class="chapter-label"><span>${String(i+1).padStart(2,'0')} /</span>${group}</div>${ls.filter(l=>l.group===group).map(l=>`<a class="chapter-row" href="#${l.id}"><span class="chapter-number">${l.number}</span><span>${l.short}<small>${l.minutes} min ${state.done.includes(l.id)?'· ✓':''}</small></span><span class="chapter-arrow">↗</span></a>`).join('')}</div>`).join('')}</div></section><section class="workbench"><div class="workbench-label">${t('À CÔTÉ DU MANUEL','BESIDE THE MANUAL')}<span>↳</span></div><a class="notepad-link" href="#notebook"><span class="mono">AUTOEXEC / ${t('PERSONNEL','PERSONAL')}</span><h2>${t('Tes binds,<br>à ta façon.','Your binds,<br>your way.')}</h2><p>${t('Un bloc-notes libre. Tes commandes, tes commentaires, tes habitudes.','An open notepad. Your commands, your comments, your habits.')}</p><span class="underlined">${t('Ouvrir mon bloc-notes','Open my notepad')} ↗</span><span class="paper-corner">⌘</span></a><div class="workbench-tools"><a href="#training"><span class="mono">20 MIN / ${t('PRATIQUE','PRACTICE')}</span><h3>${t('Le carnet de session','The session journal')}</h3><span>↗</span></a><a href="#binds"><span class="mono">.CFG / ${t('CONFIGURATION','SETUP')}</span><h3>${t('Le générateur de binds','The bind generator')}</h3><span>↗</span></a><a href="#glossary"><span class="mono">A—Z / ${t('LEXIQUE','GLOSSARY')}</span><h3>${t('Les mots du KZ','The language of KZ')}</h3><span>↗</span></a></div></section>`;}
function renderBody(html){return html.replace(/\[\[diagram:(\w+)\]\]/g,(_,kind)=>diagram(kind)).replace('[[sequence:longjump]]',sequence());}
function lessonPage(l){const next=lessons()[lessons().indexOf(l)+1],done=state.done.includes(l.id);return `<div class="lesson-heading"><span class="lesson-big-number">${l.number}</span>${header(l.title,l.intro,`${t('LEÇON','LESSON')} ${l.number} / ${l.group}`)}</div><div class="article-meta"><span>${gameName()} / ${state.game==='csgo'?'GOKZ':'CS2KZ'}</span><span>${l.level}</span><span>${l.minutes} ${t('MIN DE LECTURE','MIN READ')}</span><span>${t('EXERCICE INCLUS','EXERCISE INCLUDED')}</span></div>${l.id!=='modes'?`<div class="callout context-callout"><div class="callout-label">${gameName()} / ${t('CONTEXTE','CONTEXT')}</div><p>${state.game==='csgo'?t('Les mesures et commandes CS:GO de ce manuel ciblent GOKZ. Le mode VNL, SKZ ou KZT change les règles du mouvement.','CS:GO measurements and commands in this manual target GOKZ. VNL, SKZ and KZT use different movement rules.'):t('Les gestes généraux restent utiles ; les chiffres GOKZ sont signalés comme CS:GO. Pour CS2KZ, distingue VNL et Classic et vérifie ton mode sur le serveur.','General techniques still apply; GOKZ figures are labelled as CS:GO. For CS2KZ, distinguish VNL from Classic and check your server’s mode.')}</p></div>`:''}<div class="article-layout"><article class="article-body">${l.sections.map((s,i)=>`<section class="article-section" id="section-${i}"><h2><span class="section-index">${String(i+1).padStart(2,'0')}</span>${s.title}</h2>${renderBody(s.html)}</section>`).join('')}<section class="exercise" id="exercise"><span class="mono">${t('À TOI DE JOUER / EXERCICE PROPOSÉ','YOUR TURN / SUGGESTED EXERCISE')}</span><h3>${l.exercise.title}</h3><p>${l.exercise.text}</p></section><section class="article-section" id="lesson-sources"><h2>${t('Vérifier & approfondir','Check & explore')}</h2><p>${t('Sources consultées le 21 octobre 2026. Les exercices et les dessins sont des explications originales, pas des mesures issues du moteur.','Sources consulted on 21 October 2026. The exercises and diagrams are original explanations, not engine measurements.')}</p>${sourceLinks(l.sources)}${['strafe','ladder','bhop'].includes(l.id)?videoCards(l.id):''}</section><div class="article-bottom"><button class="btn secondary ${done?'done':''}" data-action="read" data-id="${l.id}">${readLabel(done)}</button>${next?`<a class="next" href="#${next.id}"><div><small>${t('LEÇON SUIVANTE','NEXT LESSON')}</small>${next.short}</div><span>→</span></a>`:`<a class="next" href="#training">${t('Passer à l’entraînement','Start practising')} →</a>`}</div></article><aside class="toc"><div class="mono">${t('DANS CETTE LEÇON','IN THIS LESSON')}</div>${l.sections.map((s,i)=>`<a href="#${l.id}/section-${i}"><span>${String(i+1).padStart(2,'0')}</span>${s.title}</a>`).join('')}<a href="#${l.id}/exercise">↳ ${t('Ton exercice','Your exercise')}</a><a href="#${l.id}/lesson-sources">↳ ${t('Sources','Sources')}</a><button class="mark-read ${done?'done':''}" data-action="read" data-id="${l.id}">${readLabel(done)}</button></aside></div>`;}
function readLabel(done){return done?t('✓ Leçon lue · annuler','✓ Read · undo'):t('Marquer comme lue','Mark as read');}
function videoCards(kind){return `<div class="video-grid">${videos().filter(v=>!kind||v.kind===kind).map(v=>`<a class="video-card" href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noopener noreferrer"><div class="video-graphic">${diagram(v.kind,true)}<span class="play-circle" aria-hidden="true">▷</span></div><div class="video-body"><h3>${v.title} ↗</h3><p>${v.desc}</p><p class="video-origin">KZ Guides · CS:GO / KZTimer<br>${t('Démonstration historique · anglais','Historical demonstration · English')}</p></div></a>`).join('')}</div>`;}
function workshopTabs(active){return `<nav class="workshop-tabs" aria-label="${t('Outils de configuration','Configuration tools')}"><a href="#notebook" ${active==='notebook'?'aria-current="page"':''}>01 / ${t('Mon bloc-notes','My notepad')}</a><a href="#binds" ${active==='binds'?'aria-current="page"':''}>02 / ${t('Générateur CFG','CFG generator')}</a></nav>`;}
function notebookPage(){return `${header(t('Mes binds.','My binds.'),t('Ton espace libre pour garder tes commandes et tes idées de config. Une page pour CS:GO, une pour CS2.','Your own space for commands and config ideas. One page for CS:GO, one for CS2.'),t('ATELIER / BLOC-NOTES','WORKSHOP / NOTEPAD'))}${workshopTabs('notebook')}<div class="notebook-layout"><section class="notebook"><div class="notebook-top"><label for="note-name">${t('NOM DU FICHIER','FILE NAME')}</label><div class="filename-field"><input id="note-name" type="text" maxlength="60" value="${escapeHTML(note().name)}" spellcheck="false" autocomplete="off"><span>.cfg</span></div><span class="note-game">${gameName()}</span></div><div class="editor-shell"><div id="line-numbers" aria-hidden="true">1</div><textarea id="bind-notes" spellcheck="false" autocapitalize="off" autocomplete="off" wrap="off" maxlength="100000" aria-label="${t('Mes binds personnels','My personal binds')}" placeholder="${escapeHTML(t('// Tes commandes, tes commentaires…\n// Écris ou colle tes binds ici.\n\nbind &quot;MOUSE4&quot; &quot;+jump&quot;','// Your commands, your comments…\n// Write or paste your binds here.\n\nbind &quot;MOUSE4&quot; &quot;+jump&quot;').replaceAll('&quot;','"'))}">${escapeHTML(note().text)}</textarea></div><div class="notebook-status"><span id="note-save-status" role="status"></span><span id="note-count"></span></div><div class="notebook-actions"><button class="btn" data-action="download-note-cfg">${t('Exporter .cfg','Export .cfg')} ↓</button><button class="btn secondary" data-action="copy-note">${t('Copier','Copy')}</button><button class="text-link" data-action="download-note-txt">.txt ↓</button><label class="import-note" for="import-note">+ ${t('Ajouter un fichier','Add a file')}<input type="file" id="import-note" accept=".cfg,.txt,text/plain" class="sr-only"></label></div></section><aside class="notebook-margin"><span class="margin-index">NOTE / 01</span><h2>${t('Écris comme<br>tu joues.','Write it<br>your way.')}</h2><p>${t('Une commande par ligne. Ajoute <code>//</code> devant un commentaire pour le conserver dans ton fichier CFG.','One command per line. Put <code>//</code> before a comment to keep it in your CFG file.')}</p><div class="margin-rule"></div><span class="margin-index">NOTE / 02</span><p>${t('Tes notes se sauvegardent automatiquement dans ce navigateur. Le switch FR / EN ne touche jamais à ton texte.','Your notes save automatically in this browser. Switching FR / EN never changes your text.')}</p><p>${t('Exporte une copie pour les garder ailleurs. Le changement de navigateur, d’adresse locale ou l’effacement des données ne conserve pas ce stockage.','Export a copy to keep it elsewhere. This storage does not carry over to another browser or local address, or survive cleared browser data.')}</p><div class="margin-rule"></div><a class="text-link" href="#binds">${t('Besoin d’une base ?<br>Ouvrir le générateur','Need a starting point?<br>Open the generator')} ↗</a><p class="notebook-caution">${t('Le bloc-notes ne vérifie ni n’exécute tes commandes. Le jeu n’est modifié que si tu appliques le fichier toi-même.','The notepad does not validate or execute commands. The game only changes if you apply the file yourself.')}</p></aside></div>`;}
function updateNoteUI(){if(!$('#bind-notes'))return;const text=$('#bind-notes').value;const lines=text.split('\n').length;$('#line-numbers').textContent=Array.from({length:lines},(_,i)=>i+1).join('\n');$('#note-count').textContent=`${lines} ${t(lines===1?'ligne':'lignes',lines===1?'line':'lines')} / ${text.length.toLocaleString(state.lang)} ${t('car.','chars')}`;$('#note-save-status').textContent=storageWorks?t('● Enregistré dans ce navigateur','● Saved in this browser'):t('! Sauvegarde bloquée — exporte une copie','! Saving blocked — export a copy');$('#note-save-status').classList.toggle('save-error',!storageWorks);}
function saveNote(){note().text=$('#bind-notes').value;note().name=$('#note-name').value;note().updated=new Date().toISOString();persist();updateNoteUI();}
function noteFilename(ext){return (note().name.replace(/\.(cfg|txt)$/i,'').replace(/[^a-zA-Z0-9_\-]/g,'_').slice(0,60)||'my_kz_binds')+'_'+state.game+'.'+ext;}
async function importNote(file){if(!file)return;const game=state.game;if(file.size>100000){toast(t('Le fichier dépasse 100 Ko.','The file exceeds 100 KB.'));return;}try{const imported=await file.text();const target=state.bindNotes[game];const next=target.text+(target.text&&!target.text.endsWith('\n')?'\n':'')+imported;if(next.length>100000){toast(t('Le bloc-notes est limité à 100 000 caractères.','The notepad is limited to 100,000 characters.'));return;}target.text=next;target.updated=new Date().toISOString();persist();if(page==='notebook'&&state.game===game&&$('#bind-notes')){$('#bind-notes').value=next;updateNoteUI();}toast(t('Fichier ajouté à la fin de tes notes.','File appended to your notes.'));}catch{toast(t('Ce fichier n’a pas pu être lu.','This file could not be read.'));}}
function bindsPage(){return `${header(t('La configuration.','The configuration.'),t('Prépare une base de binds simples, puis adapte-la dans ton bloc-notes.','Prepare a base of simple binds, then make it your own in the notepad.'),t('ATELIER / GÉNÉRATEUR','WORKSHOP / GENERATOR'))}${workshopTabs('binds')}<div class="bind-layout"><div class="form-panel"><h2>${t('Le preset','The preset')}</h2><div class="field"><label for="bind-game">${t('Jeu','Game')}</label><select id="bind-game"><option value="csgo" ${state.game==='csgo'?'selected':''}>CS:GO · GOKZ</option><option value="cs2" ${state.game==='cs2'?'selected':''}>CS2 · CS2KZ</option></select></div><div class="field"><label for="bind-layout">${t('Disposition du clavier','Keyboard layout')}</label><select id="bind-layout"><option value="qwerty" ${bindPrefs.layout==='qwerty'?'selected':''}>QWERTY · W A S D</option><option value="azerty" ${bindPrefs.layout==='azerty'?'selected':''}>AZERTY · Z Q S D</option></select><small>${t('Utilisée seulement avec les touches de déplacement ci-dessous.','Only used if you include the movement keys below.')}</small></div><div class="field"><label for="bind-crouch">${t('Accroupissement (maintenir)','Crouch (hold)')}</label><select id="bind-crouch"><option value="c" ${bindPrefs.crouch==='c'?'selected':''}>C</option><option value="ctrl" ${bindPrefs.crouch==='ctrl'?'selected':''}>${t('Ctrl gauche','Left Ctrl')}</option></select></div><div class="field"><label for="bind-wheel">${t('Saut à la molette','Scroll-wheel jump')}</label><select id="bind-wheel"><option value="mwheeldown" ${bindPrefs.wheel==='mwheeldown'?'selected':''}>${t('Molette vers le bas','Scroll down')}</option><option value="mwheelup" ${bindPrefs.wheel==='mwheelup'?'selected':''}>${t('Molette vers le haut','Scroll up')}</option><option value="none" ${bindPrefs.wheel==='none'?'selected':''}>${t('Ne pas modifier la molette','Leave wheel unchanged')}</option></select></div><div class="field"><label for="bind-extra">${t('Saut supplémentaire','Additional jump key')}</label><select id="bind-extra"><option value="none" ${bindPrefs.extra==='none'?'selected':''}>${t('Aucun','None')}</option><option value="mouse4" ${bindPrefs.extra==='mouse4'?'selected':''}>Mouse4 · ${t('saut seul','jump only')}</option></select></div><label class="check-field"><input type="checkbox" id="bind-move" ${bindPrefs.move?'checked':''}>${t('Attribuer aussi les touches de déplacement','Include movement keys')}</label><label class="check-field"><input type="checkbox" id="bind-plugin" ${bindPrefs.plugin?'checked':''}>${t('CP sur Alt, TP sur Mouse5 (plugin requis)','CP on Alt, TP on Mouse5 (plugin required)')}</label></div><div><div class="code-panel"><div class="code-head"><span id="cfg-filename"></span><button data-action="copy-cfg">${t('Copier','Copy')}</button></div><pre id="cfg-code" tabindex="0" aria-label="${t('Configuration générée','Generated configuration')}"></pre><div class="code-actions"><button class="btn small" data-action="download-cfg">${t('Télécharger .cfg','Download .cfg')} ↓</button><button class="btn secondary small" data-action="append-preset">${t('Ajouter à mes notes','Add to my notes')} ↗</button></div></div><p class="bind-note" id="bind-impact"></p><div class="callout amber"><div class="callout-label">${t('AVANT D’APPLIQUER','BEFORE APPLYING')}</div><p>${t('Le fichier remplace les binds des touches listées. Note leurs commandes actuelles avant de l’exécuter : <code>bind "c"</code> dans la console affiche son attribution. Supprimer le fichier n’annule pas les changements.','This file replaces the listed key bindings. Record their current commands before running it: <code>bind "c"</code> in the console displays its binding. Deleting the file does not undo these changes.')}</p></div></div></div><section class="article-section content-heading"><h2>${t('Installer la configuration','Install the configuration')}</h2><div class="steps"><div class="step"><div><h3>${t('Trouver le dossier du jeu','Find the game folder')}</h3><p>${t('Steam → propriétés du jeu → fichiers installés → parcourir. Cette méthode fonctionne sous Windows comme sous Linux.','Steam → game properties → installed files → browse. This works on Windows and Linux.')}</p></div></div><div class="step"><div><h3>${t('Placer le fichier .cfg','Place the .cfg file')}</h3><p id="cfg-path"></p></div></div><div class="step"><div><h3>${t('Exécuter dans la console','Run it in the console')}</h3><p id="cfg-exec"></p></div></div></div></section><section class="article-section"><h2>${t('Commandes & compatibilité','Commands & compatibility')}</h2><div class="table-wrap"><table><thead><tr><th>${t('Commande','Command')}</th><th>CS:GO / GOKZ</th><th>CS2 / CS2KZ</th></tr></thead><tbody>${[[t('Saut / crouch','Jump / crouch'),'+jump / +duck','+jump / +duck'],[t('Déplacement latéral','Sideways movement'),'+moveleft / +moveright','+left / +right'],['Checkpoint','sm_checkpoint','kz_cp'],[t('Téléportation','Teleport'),'sm_gocheck','kz_tp'],[t('Annuler le dernier TP','Undo last TP'),'sm_undo','kz_undo']].map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>${t('CP et TP sont des commandes de plugins. Elles ne fonctionnent pas dans une partie normale sans ce plugin. Les autres communautés peuvent employer d’autres commandes.','CP and TP are plugin commands. They do not work in a normal game without that plugin. Other communities may use different commands.')}</p><p>${t('Sur CS2, les binds combinant plusieurs actions de mouvement ou de tir sont ignorés par défaut. Certaines automatisations peuvent provoquer une exclusion des serveurs Valve. Ce preset contient seulement des commandes simples, sans null bind ni script de longjump.','In CS2, binds combining multiple movement or attack actions are ignored by default. Certain movement automation can lead to a kick from Valve servers. This preset contains only simple commands, with no null binds or longjump scripts.')}</p><p>${t('Commandes vérifiées dans les sources, sans test dans un client de jeu. Vérifie ton clavier et les règles du serveur en jeu.','Commands checked against the sources, without testing in a game client. Check your keyboard and server rules in game.')}</p>${sourceLinks(['cpgo','cpcs2','valvebind'])}</section>`;}
function cfg(){const cs2=state.game==='cs2',p=bindPrefs;const lines=[`// KZ ATLAS - ${cs2?'CS2 / CS2KZ':'CSGO / GOKZ'}`,t('// Commandes manuelles. Ne remplace pas votre autoexec.','// Manual commands. Does not replace your autoexec.'),t('// Sauvegardez vos binds actuels avant execution.','// Back up existing binds before running.'),'','bind "SPACE" "+jump"'];const affected=[t('Espace','Space')];if(p.wheel!=='none'){lines.push(`bind "${p.wheel.toUpperCase()}" "+jump"`);affected.push(p.wheel==='mwheeldown'?t('molette bas','scroll down'):t('molette haut','scroll up'));}lines.push(`bind "${p.crouch.toUpperCase()}" "+duck"`);affected.push(p.crouch.toUpperCase());if(p.extra==='mouse4'){lines.push('bind "MOUSE4" "+jump"');affected.push('Mouse4');}if(p.move){lines.push('',t('// Deplacement','// Movement'));const forward=p.layout==='azerty'?'Z':'W',left=p.layout==='azerty'?'Q':'A';lines.push(`bind "${forward}" "+forward"`,'bind "S" "+back"',`bind "${left}" "${cs2?'+left':'+moveleft'}"`,`bind "D" "${cs2?'+right':'+moveright'}"`);affected.push(`${forward} / ${left} / S / D`);}if(p.plugin){lines.push('',t('// Uniquement sur un serveur equipe du plugin','// Only on a server with the matching plugin'),`bind "ALT" "${cs2?'kz_cp':'sm_checkpoint'}"`,`bind "MOUSE5" "${cs2?'kz_tp':'sm_gocheck'}"`);affected.push('Alt','Mouse5');}return {text:lines.join('\n')+'\n',name:`kz_atlas_${state.game}.cfg`,affected};}
function updateCfg(){if(!$('#cfg-code'))return;const c=cfg();$('#cfg-code').textContent=c.text;$('#cfg-filename').textContent=c.name;$('#bind-impact').textContent=t('Touches réattribuées : ','Reassigned keys: ')+c.affected.join(', ')+'.'+(bindPrefs.extra==='mouse4'?t(' Mouse4 peut déjà servir au micro dans CS2.',' Mouse4 may already be used for voice chat in CS2.'):'');$('#cfg-path').innerHTML=t('Enregistre','Save')+` <code>${c.name}</code> `+t('dans','in')+` <code>${state.game==='cs2'?'game/csgo/cfg':'csgo/cfg'}</code>, `+t('sous le dossier du jeu. Garde ton autoexec actuel.','under the game folder. Keep your existing autoexec.');$('#cfg-exec').innerHTML=t('Tape','Type')+` <code>exec kz_atlas_${state.game}</code>. `+t('Vérifie le saut et le crouch, puis CP / TP sur un serveur compatible. Le site ne modifie pas le jeu directement.','Check jump and crouch, then CP / TP on a compatible server. The site does not modify your game directly.');}
async function copyText(text,el){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;top:-10000px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error('copy unavailable');}toast(t('Copié dans le presse-papiers.','Copied to clipboard.'));}catch{if(el?.select){el.focus();el.select();}else if(el){const range=document.createRange();range.selectNodeContents(el);const s=window.getSelection();s.removeAllRanges();s.addRange(range);}toast(t('Texte sélectionné : Ctrl+C pour copier.','Text selected: press Ctrl+C to copy.'));}}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
const ROUTINE=[['03',['Réveiller le mouvement','Warm up your movement'],['Sauts simples sur de grandes surfaces. Retrouve une arrivée contrôlée.','Simple jumps onto large surfaces. Find a controlled landing again.']],['06',['Travailler un seul geste','Work on one technique'],['Un LJ, une sortie d’échelle ou deux bhops. Même approche, même cible.','One LJ, one ladder exit or two bhops. Same approach, same target.']],['08',['Appliquer sur une map','Apply it on a map'],['Relie une courte section. Rapproche le CP si un passage reste incertain.','Link a short section. Move your CP closer if a jump is still uncertain.']],['03',['Observer & noter','Observe & record'],['Garde une chose qui fonctionne et un point précis pour la prochaine séance.','Record one thing that works and one specific focus for the next session.']]];
let logDraft={note:'',distance:'',mode:'',tech:'LJ'};
function trainingPage(){return `${header(t('Le carnet de session.','The session journal.'),t('Vingt minutes, un geste à travailler, une observation à garder.','Twenty minutes, one technique to practise, one observation to keep.'),t('PRATIQUE / ENTRAÎNEMENT','PRACTICE / TRAINING'))}<div class="training-layout"><section><div class="section-heading"><h2>${t('La routine','The routine')}</h2><span class="mono">20 MIN / 04 ${t('ÉTAPES','STEPS')}</span></div>${ROUTINE.map(([d,title,desc],i)=>`<div class="session-step"><div class="duration">${d}<small>MIN</small></div><div><h3>${t(...title)}</h3><p>${t(...desc)}</p><label><input type="checkbox" data-routine="${i}" ${state.routine.includes(i)?'checked':''}>${t('Étape terminée','Step completed')}</label></div></div>`).join('')}<button class="text-link reset-session" data-action="reset-routine">${t('Nouvelle séance','New session')} ↻</button><div class="callout"><div class="callout-label">${t('OBSERVER, PUIS COMPARER','OBSERVE, THEN COMPARE')}</div><p>${t('Ce carnet ne lit pas le jeu. Saisis tes observations et conserve le même mode pour comparer. Les durées sont une proposition, pas un protocole de performance validé.','This journal does not read game data. Enter your observations and compare within the same mode. These timings are suggestions, not a validated performance protocol.')}</p></div></section><form id="log-form" class="form-panel"><h2>${t('Noter ma séance','Record my session')}</h2><div class="field"><label for="log-mode">${t('Environnement','Environment')} / ${gameName()}</label><select id="log-mode">${(state.game==='csgo'?['VNL','SKZ','KZT']:['VNL','CKZ']).map(x=>`<option ${logDraft.mode===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="log-tech">${t('Technique travaillée','Technique practised')}</label><select id="log-tech">${['LJ','LAJ','BH','Map / route','Air strafe'].map(x=>`<option ${logDraft.tech===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="log-distance">${t('Distance (u, facultatif)','Distance (u, optional)')}</label><input id="log-distance" type="number" min="0" max="10000" step="0.001" placeholder="240.125" value="${escapeHTML(logDraft.distance)}"></div><div class="field"><label for="log-note">${t('Mon observation','My observation')}</label><textarea id="log-note" required maxlength="500" placeholder="${t('Ce qui a marché. Le prochain point à travailler…','What worked. What to practise next…')}">${escapeHTML(logDraft.note)}</textarea><small>${t('500 caractères maximum','500 characters maximum')}</small></div><p id="log-error" class="form-error" role="alert"></p><button class="btn" type="submit">${t('Enregistrer la séance','Save session')} <span>↗</span></button></form></div><section class="content-heading"><div class="section-heading"><h2>${t('Tes observations','Your observations')}</h2><button class="text-link" data-action="export-log">${t('Exporter le carnet','Export journal')} ↓</button></div><div id="log-list"></div><p class="bind-note">${t('100 entrées maximum. Ces notes restent dans ce navigateur et à cette adresse locale. Exporte une copie pour les conserver ailleurs.','Up to 100 entries. These notes stay in this browser at this local address. Export a copy to keep them elsewhere.')}</p></section>`;}
function renderLogs(){const el=$('#log-list');if(!el)return;if(!state.logs.length){el.innerHTML=`<div class="empty-state"><span>↳</span>${t('La première observation commence après ta prochaine session.','Your first observation starts after your next session.')}</div>`;return;}el.innerHTML=state.logs.map(l=>{const d=new Date(l.date),date=Number.isFinite(+d)?d.toLocaleDateString(state.lang==='en'?'en-GB':'fr-FR'):t('Date inconnue','Unknown date');return `<div class="log-row"><div><span class="mono">${escapeHTML(date)} / ${l.game==='cs2'?'CS2':'CS:GO'} · ${escapeHTML(l.mode||'')} · ${escapeHTML(l.tech||'')}${l.distance!==''&&l.distance!=null?' / '+escapeHTML(l.distance)+' u':''}</span><p>${escapeHTML(l.note||'')}</p></div><button data-delete-log="${escapeHTML(l.id)}" aria-label="${t('Supprimer la séance du','Delete session from')} ${escapeHTML(date)}">×</button></div>`;}).join('');}
function glossaryPage(){return `${header(t('Le langage du KZ.','The language of KZ.'),t('Les termes pour lire un serveur, une jumpstat ou un tutoriel. Les définitions détaillées dépendent toujours du plugin.','The terms you need to understand a server, jumpstats or a tutorial. Detailed definitions always depend on the plugin.'),t('RÉFÉRENCE / LEXIQUE','REFERENCE / GLOSSARY'))}<div class="field filter-input"><label for="glossary-filter">${t('Filtrer les termes','Filter terms')}</label><input type="text" id="glossary-filter" placeholder="pre, ladder, checkpoint…"></div><dl class="glossary-grid" id="glossary-list"></dl>${sourceLinks(['stats','changes','modesgo','modescs2'])}`;}
function renderGlossary(query=''){const filtered=glossary().filter(([a,b])=>normalize(a+' '+b).includes(normalize(query)));$('#glossary-list').innerHTML=filtered.length?filtered.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join(''):`<div class="empty-state">${t('Aucun terme trouvé.','No terms found.')}</div>`;}
function sourcesPage(){return `${header(t('Les références.','The references.'),t('Documentations des projets, code des plugins et démonstrations de la communauté.','Project documentation, plugin source code and community demonstrations.'),t('KZ ATLAS / SOURCES & MÉTHODE','KZ ATLAS / SOURCES & METHOD'))}<section class="article-section"><h2>${t('Ce qui a été vérifié','What was checked')}</h2><p>${t('Les modes, définitions et commandes ont été contrôlés dans les sources ci-dessous le 21 octobre 2026. Le code des plugins prime lorsqu’une ancienne page de documentation est contradictoire. Les commandes ont été vérifiées dans les sources, sans test dans un jeu lancé.','Modes, definitions and commands were checked against the sources below on 21 October 2026. Plugin source code takes precedence when an older documentation page conflicts with it. Commands were checked in the sources, without testing in a running game.')}</p><p>${t('Les illustrations sont des schémas originaux hors échelle. Les exercices sont des propositions pédagogiques ; aucun résultat de distance n’est garanti. La jumpstat montrée en exemple est fictive.','The illustrations are original diagrams, not to scale. The exercises are teaching suggestions; no distance result is guaranteed. The sample jumpstats are fictional.')}</p><div class="callout"><div class="callout-label">${t('POUR GARDER LE GUIDE FIABLE','KEEPING THE GUIDE RELIABLE')}</div><p>${t('Vérifie toujours le jeu, le plugin et le mode. Les projets évoluent : cette copie locale ne met pas ses sources à jour automatiquement. Consulte les documents officiels si le comportement change.','Always check the game, plugin and mode. Projects evolve: this local copy does not update its sources automatically. Consult the official documentation if behaviour changes.')}</p></div></section><section><div class="section-heading"><h2>${t('Voir les gestes en jeu','Watch the techniques in game')}</h2><span class="mono">KZ GUIDES / ${t('ANGLAIS','ENGLISH')}</span></div><p>${t('Ces démonstrations historiques concernent CS:GO / KZTimer. Elles illustrent les gestes ; leurs réglages et valeurs ne sont pas des règles CS2. Liens vérifiés, lecture vidéo non testée.','These historical demonstrations cover CS:GO / KZTimer. They illustrate the techniques; their settings and values are not CS2 rules. Links checked; video playback not tested.')}</p>${videoCards()}<p class="bind-note">${t('Les vidéos s’ouvrent sur YouTube et nécessitent Internet. Aucun lecteur tiers, suivi ou média distant n’est chargé à l’ouverture du site.','Videos open on YouTube and need an Internet connection. No third-party player, tracker or remote media loads when you open this site.')}</p></section><section class="sources-group"><h2>${t('Documents de référence','Reference documents')}</h2>${Object.entries(sources()).map(([id,s],i)=>`<a class="source-card" href="${s.url}" target="_blank" rel="noopener noreferrer"><span class="mono">${String(i+1).padStart(2,'0')}</span><div><h3>${s.title}</h3><p>${s.desc}</p><div class="source-domain">${s.type.toUpperCase()} · ${new URL(s.url).hostname}</div></div><span>↗</span></a>`).join('')}</section><section class="article-section content-heading"><h2>${t('Un site local','A local website')}</h2><p>${t('Le manuel, la recherche, les schémas, le bloc-notes et le générateur fonctionnent sans Internet. Ouvre index.html directement, ou lance le serveur fourni pour une adresse locale stable. Seuls les liens externes demandent une connexion.','The manual, search, diagrams, notepad and generator work offline. Open index.html directly, or run the included server for a stable local address. Only external links need a connection.')}</p><p>${t('Ce site n’installe pas un serveur de jeu, ne lit pas tes statistiques Steam et ne change pas tes fichiers Counter-Strike. Les progrès et notes sont enregistrés uniquement dans le navigateur utilisé.','This site does not install a game server, read your Steam statistics or change your Counter-Strike files. Progress and notes are stored only in the browser you use.')}</p><p>${t('KZ Atlas est indépendant, sans affiliation avec Valve ou KZGlobalTeam. Les contenus de référence et les vidéos appartiennent à leurs auteurs.','KZ Atlas is independent and is not affiliated with Valve or KZGlobalTeam. Reference material and videos belong to their authors.')}</p></section>`;}
function specialPages(){return [{id:'notebook',title:t('Mes binds / bloc-notes','My binds / notepad'),desc:t('Écrire et sauvegarder ses commandes personnelles. Export CFG / TXT.','Write and save your own commands. Export CFG / TXT.')},{id:'binds',title:t('Générateur CFG','CFG generator'),desc:'CFG, jump, crouch, CP, TP, QWERTY, AZERTY, console, configuration'},{id:'training',title:t('Entraînement','Practice'),desc:t('Routine, carnet, séances et progression','Routine, journal, sessions and progress')},{id:'glossary',title:t('Lexique','Glossary'),desc:glossary().map(x=>x.join(' ')).join(' · ')},{id:'sources',title:t('Sources & méthode','Sources & method'),desc:t('Tutoriels, vidéos, documents officiels, code des plugins','Tutorials, videos, official documents, plugin source code')}];}
function search(query=''){const q=normalize(query.trim()),list=[...lessons(),...specialPages()];const found=list.filter(l=>normalize(l.title+' '+l.desc+' '+(l.short||'')+' '+(l.sections||[]).map(s=>s.title+' '+cleanText(s.html)).join(' ')).includes(q)).slice(0,12);$('#search-results').innerHTML=found.length?found.map(l=>`<a class="search-result" href="#${l.id}" data-search-result><span>${l.number?t('LEÇON ','LESSON ')+l.number:t('OUTIL','TOOL')}</span><h3>${l.title}</h3><p>${escapeHTML(l.desc.length>125?l.desc.slice(0,122)+'…':l.desc)}</p></a>`).join(''):`<div class="search-empty">${t('Aucun résultat. Essaie « saut », « CP » ou « ladder ».','No results. Try “jump”, “CP” or “ladder”.')}</div>`;}
function openSearch(){closeMenu();const dialog=$('#search-dialog');if(!dialog.open)dialog.showModal();$('#search-input').value='';search();$('#search-input').focus();}
function closeMenu(){$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open');$('.index-trigger').setAttribute('aria-expanded','false');$('#sidebar').setAttribute('inert','');}
function openMenu(){$('#sidebar').classList.add('open');$('#sidebar').removeAttribute('inert');document.body.classList.add('menu-open');$('.index-trigger').setAttribute('aria-expanded','true');$('#sidebar .icon-button').focus();}
function route(force=false,keepScroll=false){const raw=location.hash.slice(1)||'home',[id,anchor]=raw.split('/'),lesson=lessons().find(l=>l.id===id);if(!['home','notebook','binds','training','glossary','sources'].includes(id)&&!lesson){location.replace('#home');return;}if(page===id&&!force){closeMenu();if(anchor)document.getElementById(anchor)?.scrollIntoView({behavior:'smooth'});return;}const y=window.scrollY;stopSequence();seqIndex=0;page=id;closeMenu();navigation();const names={home:t('Vue d’ensemble','Overview'),notebook:t('Mes binds / bloc-notes','My binds / notepad'),binds:t('Générateur CFG','CFG generator'),training:t('Entraînement','Practice'),glossary:t('Lexique','Glossary'),sources:t('Sources & méthode','Sources & method')};$('#breadcrumb').textContent=lesson?`${lesson.number} / ${lesson.short}`:names[id];document.title=`${lesson?lesson.short:names[id]} — KZ Atlas`;let html=lesson?lessonPage(lesson):({home,notebook:notebookPage,binds:bindsPage,training:trainingPage,glossary:glossaryPage,sources:sourcesPage}[id])();if(!storageWorks)html=`<div class="storage-warning">${t('Stockage local bloqué. Exporte tes notes pour les conserver.','Local storage blocked. Export your notes to keep them.')}</div>`+html;$('#main').innerHTML=html;$('#main').dataset.page=id;if(id==='longjump')drawSequence();if(id==='binds')updateCfg();if(id==='notebook'){updateNoteUI();$('#bind-notes').addEventListener('scroll',()=>{$('#line-numbers').scrollTop=$('#bind-notes').scrollTop;});}if(id==='training')renderLogs();if(id==='glossary')renderGlossary();if(keepScroll)window.scrollTo(0,y);else if(anchor)document.getElementById(anchor)?.scrollIntoView();else window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.lang){if(state.lang===b.dataset.lang)return;state.lang=b.dataset.lang;persist();route(true,true);return;}
 if(b.dataset.game){state.game=b.dataset.game;persist();route(true,true);return;}
 if(b.hasAttribute('data-search-result')){$('#search-dialog').close();if(location.hash===b.getAttribute('href'))route(true);return;}
 if(b.dataset.phase!==undefined){stopSequence();seqIndex=Number(b.dataset.phase);drawSequence();return;}
 if(b.dataset.deleteLog){state.logs=state.logs.filter(l=>l.id!==b.dataset.deleteLog);persist();renderLogs();toast(t('Entrée supprimée.','Entry deleted.'));return;}
 switch(b.dataset.action){
 case 'skip':e.preventDefault();$('#main').focus();$('#main').scrollIntoView();break;
 case 'search':openSearch();break;case 'close-search':$('#search-dialog').close();break;
 case 'menu':$('#sidebar').classList.contains('open')?closeMenu():openMenu();break;
 case 'close-menu':closeMenu();$('.index-trigger').focus();break;
 case 'read':{const id=b.dataset.id;state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];persist();navigation();$$('[data-action="read"]').forEach(el=>{el.textContent=readLabel(state.done.includes(el.dataset.id));el.classList.toggle('done',state.done.includes(el.dataset.id));});toast(state.done.includes(id)?t('Leçon ajoutée à ton parcours.','Lesson added to your progress.'):t('Leçon remise à lire.','Lesson marked unread.'));break;}
 case 'seq-next':stopSequence();seqIndex=(seqIndex+1)%PHASES.length;drawSequence();break;
 case 'seq-prev':stopSequence();seqIndex=(seqIndex+PHASES.length-1)%PHASES.length;drawSequence();break;
 case 'seq-play':if(seqTimer)stopSequence();else{b.textContent=t('Mettre en pause','Pause');seqTimer=setInterval(()=>{seqIndex=(seqIndex+1)%PHASES.length;drawSequence();},2400);}break;
 case 'copy-cfg':copyText(cfg().text,$('#cfg-code'));break;
 case 'download-cfg':{const c=cfg();download(c.name,c.text);toast(t('CFG préparée pour le téléchargement.','CFG prepared for download.'));break;}
 case 'append-preset':{const extra=(note().text?'\n':'')+cfg().text;if(note().text.length+extra.length>100000){toast(t('Bloc-notes plein. Exporte tes notes.','Notepad full. Export your notes.'));break;}note().text+=extra;note().updated=new Date().toISOString();persist();location.hash='#notebook';toast(t('Preset ajouté à la fin de tes notes.','Preset appended to your notes.'));break;}
 case 'copy-note':copyText(note().text,$('#bind-notes'));break;
 case 'download-note-cfg':case 'download-note-txt':download(noteFilename(b.dataset.action.endsWith('cfg')?'cfg':'txt'),note().text);toast(t('Tes notes sont prêtes à télécharger.','Your notes are ready to download.'));break;
 case 'reset-routine':state.routine=[];persist();$$('[data-routine]').forEach(c=>c.checked=false);toast(t('Routine prête pour une nouvelle séance.','Routine ready for a new session.'));break;
 case 'export-log':{const lines=[t('# Mon carnet KZ Atlas','# My KZ Atlas journal'),'',...state.logs.map(l=>`## ${String(l.date||'').slice(0,10)} · ${l.game==='cs2'?'CS2':'CS:GO'} · ${l.mode} · ${l.tech}\n${l.distance!==''?'Distance: '+l.distance+' u\n':''}\n${l.note}\n`)];download('kz-atlas-journal.md',lines.join('\n'));toast(t('Carnet prêt à télécharger.','Journal ready to download.'));break;}
 }});
$('.nav-shade').addEventListener('click',closeMenu);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search-input')search(el.value);if(el.id==='glossary-filter')renderGlossary(el.value);if(['bind-notes','note-name'].includes(el.id))saveNote();if(el.id==='log-note')logDraft.note=el.value;if(el.id==='log-distance')logDraft.distance=el.value;});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='bind-game'){state.game=el.value;persist();route(true,true);return;}if(el.id==='import-note'){importNote(el.files[0]);el.value='';return;}const fields={'bind-layout':'layout','bind-crouch':'crouch','bind-wheel':'wheel','bind-extra':'extra','bind-move':'move','bind-plugin':'plugin'};if(fields[el.id]){bindPrefs[fields[el.id]]=el.type==='checkbox'?el.checked:el.value;updateCfg();}if(el.dataset.routine!==undefined){const n=Number(el.dataset.routine);state.routine=el.checked?[...new Set([...state.routine,n])]:state.routine.filter(x=>x!==n);persist();}if(el.id==='log-mode')logDraft.mode=el.value;if(el.id==='log-tech')logDraft.tech=el.value;});
document.addEventListener('submit',e=>{if(e.target.id!=='log-form')return;e.preventDefault();const text=$('#log-note').value.trim(),distance=$('#log-distance').value;if(!text){$('#log-error').textContent=t('Ajoute une observation.','Add an observation.');return;}if(distance!==''&&(!Number.isFinite(Number(distance))||Number(distance)<0||Number(distance)>10000)){$('#log-error').textContent=t('Distance attendue : 0 à 10 000 unités.','Expected distance: 0 to 10,000 units.');return;}state.logs.unshift({id:String(Date.now())+'-'+Math.random().toString(36).slice(2,8),date:new Date().toISOString(),game:state.game,mode:$('#log-mode').value,tech:$('#log-tech').value,distance:distance===''?'':Number(distance),note:text});state.logs=state.logs.slice(0,100);const ok=persist();$('#log-note').value='';$('#log-distance').value='';$('#log-error').textContent='';logDraft={note:'',distance:'',mode:$('#log-mode').value,tech:$('#log-tech').value};renderLogs();toast(ok?t('Séance enregistrée.','Session saved.'):t('Sauvegarde bloquée. Exporte le carnet.','Saving blocked. Export the journal.'));});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){closeMenu();$('.index-trigger').focus();}if(e.key==='Tab'&&$('#sidebar').classList.contains('open')){const items=$$('a,button',$('#sidebar'));if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSequence();});
window.addEventListener('hashchange',()=>route());
route();
